// Owner-approved map-object player inspection; no Foundry world writes or item grants.
const CONFIG={"region":"CAVB3E32BD6B01BD","kind":"note","alt":"Owner-approved closeup of a handwritten note on the Study desk","key":"study-note","image":"worlds/cabin-in-the-ashen-veil/assets/puzzle-closeups/father-study-587-note-owner-map-crop-v001.png","scene":"CAVHG05Scene0001","title":"Allen\u0027s Desk - The Note"};
const NS='dicebox-campaign-helper',SLOT='__CAV_587_INSPECT_'+CONFIG.kind;
if(game.world?.id!=='cabin-in-the-ashen-veil'||game.version!=='14.367'||scene?.id!==CONFIG.scene||region?.id!==CONFIG.region)return;
const ev=event?.name,prior=globalThis[SLOT];
if(ev==='behaviorUnviewed'||ev==='behaviorDeactivated'){
 if(prior?.handler&&canvas?.stage)canvas.stage.off('pointertap',prior.handler);
 delete globalThis[SLOT];return;
}
if(ev!=='behaviorViewed'||game.user?.isGM)return;
if(prior?.handler&&canvas?.stage)canvas.stage.off('pointertap',prior.handler);
const handler=async e=>{
 if(!canvas?.ready||canvas.scene?.id!==CONFIG.scene||game.user.isGM||(e.button!==undefined&&e.button!==0))return;
 const pt=canvas.stage.toLocal(e.global);
 if(!region.testPoint({x:pt.x,y:pt.y,elevation:0}))return;
 const busy=SLOT+'_OPEN';if(globalThis[busy])return;globalThis[busy]=true;
 try{
  const tokens=canvas.tokens?.controlled?.filter(t=>t.actor?.type==='character'&&t.actor.testUserPermission(game.user,'OWNER'))||[];
  const token=tokens.length===1?tokens[0].document:null;
  const options=Array.from({length:10},(_,n)=>'<option value="'+n+'">'+n+'</option>').join('');
  const done=CONFIG.kind==='note'?region.getFlag(NS,'cavStudy587Learned')?.status==='done':region.getFlag(NS,'cavDonovan587LockboxClaim')?.status==='done';
  const text=CONFIG.kind==='note'?'Among Allen\u2019s notes, a small sheet carries three carefully written numerals.':done?'The heavy lockbox has already been opened.':'The lockbox is solidly made, with a three-number mechanism.';
  const inputs=CONFIG.kind==='box'&&!done&&token?'<div style="display:flex;justify-content:center;gap:0.75rem;margin:0.5rem"><label>First<br/><select id="cav587-digit-0">'+options+'</select></label><label>Second<br/><select id="cav587-digit-1">'+options+'</select></label><label>Third<br/><select id="cav587-digit-2">'+options+'</select></label></div>':'';
  const html='<div style="max-width:600px;margin:auto;text-align:center"><img src="'+CONFIG.image+'" alt="'+CONFIG.alt+'" style="max-width:100%;max-height:65vh;border:1px solid #806e54;border-radius:4px"/><p>'+text+'</p>'+inputs+(token?'':'<small>Select exactly one character token to interact.</small>')+'</div>';
  await foundry.applications.api.DialogV2.prompt({
   window:{title:CONFIG.title},content:html,
   ok:{label:CONFIG.kind==='note'?'Examine Note':done?'Close':'Try Combination',callback:async()=>{
    if(!token||done)return true;
    const gm=game.users.activeGM;if(!gm?.active){ui.notifications?.warn('The GM is unavailable for this interaction.');return false;}
    let digits;
    if(CONFIG.kind==='box'){digits=[0,1,2].map(n=>Number(document.getElementById('cav587-digit-'+n)?.value));if(digits.some(x=>!Number.isInteger(x)||x<0||x>9)){ui.notifications?.warn('Choose three numbers.');return false;}}
    await ChatMessage.create({content:CONFIG.kind==='note'?'<p>You study the note on Allen\u2019s desk.</p>':'<p>You try the lockbox mechanism.</p>',whisper:[gm.id,game.user.id],flags:{[NS]:{cav587Request:{version:1,action:CONFIG.kind==='note'?'study-note-read':'donovan-lockbox-try',sceneId:CONFIG.scene,regionId:CONFIG.region,tokenId:token.id,...(digits?{digits}:{})}}}});
    return true;
   }},rejectClose:false
  });
 }catch(err){console.warn('[CAV 587 Inspect] click UI unavailable',err);}
 finally{globalThis[busy]=false;}
};
if(canvas?.stage){canvas.stage.on('pointertap',handler);globalThis[SLOT]={handler};}

